  const CURRENCY_MAP = {
    USD: { code: 'USD', symbol: '$', minTrade: 1.0 },
    EUR: { code: 'EUR', symbol: '€', minTrade: 1.0 },
    GBP: { code: 'GBP', symbol: '£', minTrade: 1.0 },
    AUD: { code: 'AUD', symbol: 'A$', minTrade: 1.5 },
    CAD: { code: 'CAD', symbol: 'C$', minTrade: 1.5 },
    INR: { code: 'INR', symbol: '₹', minTrade: 85.0 },
    AED: { code: 'AED', symbol: 'د.إ', minTrade: 4.0 },
    PHP: { code: 'PHP', symbol: '₱', minTrade: 50.0 },
    NGN: { code: 'NGN', symbol: '₦', minTrade: 2000.0 },
    SAR: { code: 'SAR', symbol: 'SAR ', minTrade: 4.0 },
    THB: { code: 'THB', symbol: '฿', minTrade: 40.0 },
    ZAR: { code: 'ZAR', symbol: 'R', minTrade: 20.0 },
    CNY: { code: 'CNY', symbol: '¥', minTrade: 8.0 }
  };

  function getTMCurrencyInfo(curCode = tmState.currency) {
    return CURRENCY_MAP[curCode] || CURRENCY_MAP.USD;
  }

  function getTMBrokerMinTrade(curCode = tmState.currency) {
    const info = getTMCurrencyInfo(curCode);
    if (curCode === 'USD') return Math.max(1.0, Number(tmState.minStakeLimit) || 1.0);
    return info.minTrade || 1.0;
  }

  function fmtMoney(val, cur = mxState.currency, decimals = 2) {
    const c = CURRENCY_MAP[cur] || CURRENCY_MAP.USD;
    const n = Number(val);
    if (!isFinite(n)) return `${c.symbol}0.00`;
    const neg = n < 0;
    const abs = Math.abs(n);
    let str;
    if (abs >= 1e9) str = (abs / 1e9).toFixed(2) + 'B';
    else if (abs >= 1e7) str = (abs / 1e6).toFixed(2) + 'M';
    else str = abs.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
    return `${neg ? '-' : ''}${c.symbol}${str}`;
  }

  function escHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

