  // 7.0 WEB AUDIO SYNTHESIZER, 2-WAY VOICE, THEMES, FIREWORKS & P&L SHARE
  // -------------------------------------------------------------------------
  let sharedAudioContext = null;
  let currentSpeechUtterance = null;
  let audioVisTimeout = null;
  let genieAudioRecDest = null;
  let genieAudioRecActive = false;

  function getSharedAudioContext() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return null;
      if (!sharedAudioContext || sharedAudioContext.state === 'closed') {
        sharedAudioContext = new AudioCtx();
        genieAudioRecDest = null;
      }
      if (sharedAudioContext.state === 'suspended') {
        sharedAudioContext.resume().catch(() => {});
      }
      return sharedAudioContext;
    } catch {
      return null;
    }
  }

  function ensureGenieAudioRecStream() {
    try {
      const ctx = getSharedAudioContext();
      if (!ctx || typeof ctx.createMediaStreamDestination !== 'function') return null;
      if (!genieAudioRecDest) {
        genieAudioRecDest = ctx.createMediaStreamDestination();
      }
      return genieAudioRecDest.stream || null;
    } catch {
      return null;
    }
  }

  try {
    const unlockAudioCtx = () => {
      try {
        const ctx = getSharedAudioContext();
        if (ctx && ctx.state === 'suspended') ctx.resume().catch(() => {});
      } catch {}
    };
    window.addEventListener('pointerdown', unlockAudioCtx, { passive: true });
    window.addEventListener('touchstart', unlockAudioCtx, { passive: true });
    window.addEventListener('keydown', unlockAudioCtx, { passive: true });
    if ('speechSynthesis' in window) {
      window.speechSynthesis.getVoices();
      if (typeof window.speechSynthesis.addEventListener === 'function') {
        window.speechSynthesis.addEventListener('voiceschanged', () => {
          try { window.speechSynthesis.getVoices(); } catch {}
        });
      }
    }
  } catch {}

