            <div class="al-tools-pack-grid">
              ${SOUND_PACKS.map(pk => {
                const act = toolsState.toneStyle === pk.id;
                return `
                  <div class="al-tm-tile" style="padding:7px;border-color:${act ? pk.border : 'rgba(148,163,184,0.12)'};background:${act ? 'rgba(255,255,255,0.05)' : 'rgba(2,6,23,0.34)'};display:flex;flex-direction:column;gap:4px;">
                    <div style="display:flex;justify-content:space-between;align-items:center;gap:4px;flex-wrap:wrap;">
                      <strong data-tools-pack="${pk.id}" style="font-size:9.5px;color:${act ? pk.text : '#e2e8f0'};cursor:pointer;">${escHtml(pk.name)}</strong>
                      <span class="al-tag-sq" style="border-color:rgba(148,163,184,0.16);color:#94a3b8;">${escHtml(pk.badge)}</span>
                    </div>
                    <div style="font-size:8px;color:#64748b;line-height:1.25;">${escHtml(pk.desc)}</div>
                    <div style="display:flex;gap:4px;margin-top:auto;">
                      <button data-tools-pack="${pk.id}" class="al-micro-btn" style="flex:1;${act ? `background:${pk.border};color:#090d16;border-color:${pk.border};font-weight:800;` : ''}">${act ? '✓ Active' : 'Select'}</button>
                      <button data-tools-audition="${pk.id}" class="al-micro-btn" style="flex-shrink:0;color:#fbbf24;border-color:rgba(245,158,11,0.35);">▶</button>
                    </div>
                  </div>
                `;
              }).join('')}
            </div>
